recipes.code:
{
  "inputs": [
    {
      "id": "mailkite-api-key",
      "type": "promptString",
      "description": "MailKite API key (mk_live_…) from the dashboard at https://app.mailkite.dev",
      "password": true
    }
  ],
  "servers": {
    "mailkite": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@mailkite/mcp@0.13.0"
      ],
      "env": {
        "MAILKITE_API_KEY": "${input:mailkite-api-key}"
      }
    }
  }
}
